// 1. claim one job in a short transaction of its own
data class Job(val id: Long, val payload: String, val attempts: Int)

fun claim(conn: Connection, worker: String): Job? {
    conn.autoCommit = false
    val job = conn.prepareStatement(
        """
        UPDATE jobs SET status = 'running', locked_by = ?, locked_at = now(), attempts = attempts + 1
        WHERE job_id = (SELECT job_id FROM jobs
                        WHERE status = 'queued' AND kind = 'send_receipt' AND run_after <= now()
                        ORDER BY run_after, job_id LIMIT 1
                        FOR UPDATE SKIP LOCKED)
        RETURNING job_id, payload, attempts
        """,
    ).use { ps ->
        ps.setString(1, worker)
        ps.executeQuery().use { rs -> if (rs.next()) Job(rs.getLong(1), rs.getString(2), rs.getInt(3)) else null }
    }
    conn.commit()                   // the claim is visible to everyone, and no lock is held
    return job
}

// 2. do the work, then record the outcome in a second short transaction
interface ReceiptMailer { fun send(payload: String, idempotencyKey: String) }

fun runOne(conn: Connection, worker: String, mail: ReceiptMailer) {
    val job = claim(conn, worker) ?: return
    val ok = runCatching { mail.send(job.payload, idempotencyKey = "job-${job.id}") }.isSuccess
    conn.prepareStatement(
        """
        UPDATE jobs SET status = CASE WHEN ? THEN 'done' WHEN attempts >= 3 THEN 'failed' ELSE 'queued' END,
                        run_after = now() + attempts * interval '1 minute',
                        locked_by = NULL, locked_at = NULL
        WHERE job_id = ? AND locked_by = ?
        """,
    ).use { ps -> ps.setBoolean(1, ok); ps.setLong(2, job.id); ps.setString(3, worker); ps.executeUpdate() }
    conn.commit()
}

// 4. the same key on every attempt of one job: a repeat is harmless
mail.send(job.payload, idempotencyKey = "job-${job.id}")   // not a random UUID per attempt

// with a lock-held design instead (BEGIN, claim, work, done, COMMIT), a crash rolls the claim
// back and the job is simply queued again, but attempts rolls back too: it can't count crashes
